Item.method_code:
const { getState, rows, relatedTypeName } = options;
const { editableItems, grid } = getState();
const selectedRows = grid.selectedRows;
if (selectedRows.length === 0) {
	return { hidden: true };
}

const hidden = selectedRows.some((rowId) => {
	const relatedId = rows.get(rowId, 'related_id');
	const isEditableItem = editableItems.has(relatedId);
	const isNew = ArasModules.item.isNew(relatedTypeName, relatedId);
	return isNew || !isEditableItem;
});

return { hidden };
